ALTER TYPE public.school_role ADD VALUE IF NOT EXISTS 'headmaster';
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, username text NOT NULL UNIQUE, CONSTRAINT username_format CHECK (username ~ '^[a-z0-9._-]{3,40}$'));
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own username read" ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid() OR EXISTS (SELECT 1 FROM public.school_members m WHERE m.user_id = profiles.id AND public.has_perm(m.school_id,'users')));
CREATE OR REPLACE FUNCTION public.create_username_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.email LIKE '%@accounts.schoolsys.local' THEN INSERT INTO public.profiles(id,username) VALUES (NEW.id,split_part(NEW.email,'@',1)); END IF; RETURN NEW; END $$;
CREATE TRIGGER username_profile_on_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_username_profile();
CREATE OR REPLACE FUNCTION public.has_perm(_school uuid, _perm text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE public.member_role(_school)::text WHEN 'head' THEN true WHEN 'admin' THEN _perm IN ('view','students','finance','attendance','settings','users','reports','fees_setup') WHEN 'headmaster' THEN _perm IN ('view','reports') WHEN 'bursar' THEN _perm IN ('view','students','finance','reports','fees_setup') WHEN 'deputy_head' THEN _perm IN ('view','students','attendance') WHEN 'teacher' THEN _perm IN ('view','attendance') ELSE false END $$;
ALTER TABLE public.expenses ADD COLUMN voucher_reference text;
CREATE OR REPLACE FUNCTION public.audit_phase_one() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_logs(school_id,user_id,action,record_type,record_id) VALUES (CASE WHEN TG_TABLE_NAME='schools' THEN NEW.id ELSE NEW.school_id END,auth.uid(),TG_TABLE_NAME||'.'||lower(TG_OP),TG_TABLE_NAME,NEW.id); RETURN NEW; END $$;
CREATE TRIGGER audit_school_settings AFTER UPDATE ON public.schools FOR EACH ROW EXECUTE FUNCTION public.audit_phase_one();
CREATE TRIGGER audit_expense_entries AFTER INSERT ON public.expenses FOR EACH ROW EXECUTE FUNCTION public.audit_phase_one();